-- Generated by `pnpm decisions:seed` from docs/planning/decisions.md (decision 191): the log's
-- entries as decisions, numbered as in the log, active unless a later entry replaces them.
-- Do not edit by hand.
insert into public.decisions
  (number, statement, reason, status, decided_by_name, decided_at, origin, origin_ref)
overriding system value
values
  (195, 'Changes to slice 2.2 after an independent review, before it merged. A decision is active only when every message of the bot''s turn is the decider''s and none came with other people''s words from the thread (`inbound_messages.carried_context`); otherwise it is proposed. A proposal quotes the decision it replaces, which stays active until the proposal is confirmed, and is left alone if it was replaced meanwhile. An imported decision keeps its number in the log, and decisions recorded in threads are numbered from 1000. The decisions put before a message must share at least two words with it, ranked by matches over length; a message of stop words gets none, and Postgres notices no longer reach the logs. A second press of Confirm says who confirmed it if the first note was lost', 'The review found that text another person posted in the thread could steer the bot into recording an active decision in the asker''s name, that a confirmed proposal could silently retire an unrelated decision, that most messages drew in irrelevant decisions, and that "decision 194" would have meant two things', 'active', 'the owner', '2026-11-25T00:00:00Z', 'import', '195')
on conflict (origin, origin_ref) where origin_ref is not null do nothing;
